const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close menu':'Open menu');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu')}));
const courses={vocal:['VOCAL MUSIC','Your voice. Your expression.','Explore classical, semi-classical and light music. Build a connection with melody, expression and the joy of singing.','आ','vocal'],strings:['GUITAR','A few strings. Endless possibilities.','Discover melody and rhythm through the guitar. Ask us about lessons, starting points and finding a class that suits your experience.','♮','guitar'],keys:['HARMONIUM & KEYBOARD','Let your fingers find a melody.','Explore the expressive world of harmonium and keyboard. Discover how individual notes become the songs you love.','♬','harmonium and keyboard'],rhythm:['TABLA & PERCUSSION','Every beat tells a story.','Connect with rhythm through tabla and percussion. Explore patterns, timing and the joy of playing together.','◉','tabla']};const tabs=[...document.querySelectorAll('[data-course]')];tabs.forEach((b,i)=>{b.addEventListener('click',()=>{tabs.forEach(t=>t.setAttribute('aria-selected',t===b));const c=courses[b.dataset.course];document.querySelector('#course-label').textContent=c[0];document.querySelector('#course-heading').textContent=c[1];document.querySelector('#course-description').textContent=c[2];document.querySelector('.course-symbol').textContent=c[3];document.querySelector('#course-link').innerHTML='Enquire about '+c[4]+' classes <span>↗</span>';document.querySelector('#course-panel').setAttribute('aria-labelledby',b.id)});b.addEventListener('keydown',e=>{if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click()}})});
let audio;document.querySelectorAll('[data-frequency]').forEach(b=>b.addEventListener('click',async()=>{try{audio??=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();const osc=audio.createOscillator(),gain=audio.createGain(),t=audio.currentTime;osc.type='sine';osc.frequency.value=+b.dataset.frequency;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.25,t+.025);gain.gain.exponentialRampToValueAtTime(.001,t+1.1);osc.connect(gain);gain.connect(audio.destination);osc.start(t);osc.stop(t+1.15);osc.onended=()=>{osc.disconnect();gain.disconnect()};b.classList.add('playing');setTimeout(()=>b.classList.remove('playing'),350);document.querySelector('#sound-status').textContent='YOU PLAYED '+b.querySelector('span').textContent.toUpperCase()+' · YOUR FIRST NOTE IS ALREADY MUSIC ♪'}catch{document.querySelector('#sound-status').textContent='Sound is unavailable in this browser. Try another browser to play.'}}));
const dialog=document.querySelector('#lightbox');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{dialog.querySelector('img').src=b.dataset.image;dialog.querySelector('img').alt=b.querySelector('img').alt;dialog.querySelector('p').textContent=b.dataset.caption;dialog.showModal()}));dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelector('#year').textContent=new Date().getFullYear();

document.querySelector('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget),name=data.get('name').trim();if(!name){document.querySelector('#enquiry-name').focus();return}const message='Hello Raag Music Academy! My name is '+name+'.\nI am interested in '+data.get('course')+' classes.'+(data.get('message').trim()?'\n'+data.get('message').trim():'')+'\nPlease share class timings, fees and availability.';window.open('https://wa.me/918505081961?text='+encodeURIComponent(message),'_blank','noopener,noreferrer')});
